 if(member){const action=status==='running'?'pause':status==='paused'?'resume':'start';return `<div class="actions"><button type="button" class="btn" data-account-task="${taskId}" data-account-action="${action}">${action==='pause'?'暂停':recovery==='blocked'?'处理后继续':action==='resume'?'继续':'启动'}</button>${env.browser_alive?`<a class="btn" href="${esc(env.browser_url)}" target="_blank" rel="noopener">打开执行浏览器</a>`:'<button type="button" class="btn" disabled>打开执行浏览器</button>'}<span class="meta">${esc(env.label)} · ${esc(recovery?selectionRecoveryLabel(recovery):status==='completed'?'目标已调整，可继续':status==='running'?(({outside_window:'非执行时段 · 保留会话',resting:'休息中 · 保留会话',planning:'等待规划'})[member?.availability?.state]||statuses[status]||status):statuses[status]||status)}</span></div>`;}
 const isBoss=state.definitions?.find(t=>t.id===taskId)?.config.engine==='boss_sourcing'||run?.environment_id==='boss:default'||run?.mode?.startsWith('boss_');
